mapper.select:
SELECT COUNT(*)
FROM wish
WHERE member_no = #{memberNo}
AND store_id = #{storeId}
AND wish_type = 'STORE'

mapper.delete:
DELETE FROM wish
WHERE member_no = #{memberNo}
AND store_id = #{storeId}
AND wish_type = 'STORE'

